public class InnerMediaCapturePipelineGridViewConfigurationFactory(Action<Humidifier.Chime.MediaCapturePipelineTypes.GridViewConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Chime.MediaCapturePipelineTypes.GridViewConfiguration>
{

    internal InnerMediaCapturePipelinePresenterOnlyConfigurationFactory PresenterOnlyConfigurationFactory { get; set; }

    internal InnerMediaCapturePipelineVideoAttributeFactory VideoAttributeFactory { get; set; }

    internal InnerMediaCapturePipelineHorizontalLayoutConfigurationFactory HorizontalLayoutConfigurationFactory { get; set; }

    internal InnerMediaCapturePipelineActiveSpeakerOnlyConfigurationFactory ActiveSpeakerOnlyConfigurationFactory { get; set; }

    internal InnerMediaCapturePipelineVerticalLayoutConfigurationFactory VerticalLayoutConfigurationFactory { get; set; }

    protected override Humidifier.Chime.MediaCapturePipelineTypes.GridViewConfiguration Create()
    {
        var gridViewConfigurationResult = CreateGridViewConfiguration();
        factoryAction?.Invoke(gridViewConfigurationResult);

        return gridViewConfigurationResult;
    }

    private Humidifier.Chime.MediaCapturePipelineTypes.GridViewConfiguration CreateGridViewConfiguration()
    {
        var gridViewConfigurationResult = new Humidifier.Chime.MediaCapturePipelineTypes.GridViewConfiguration();

        return gridViewConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Chime.MediaCapturePipelineTypes.GridViewConfiguration result)
    {
        base.CreateChildren(result);

        result.PresenterOnlyConfiguration ??= PresenterOnlyConfigurationFactory?.Build();
        result.VideoAttribute ??= VideoAttributeFactory?.Build();
        result.HorizontalLayoutConfiguration ??= HorizontalLayoutConfigurationFactory?.Build();
        result.ActiveSpeakerOnlyConfiguration ??= ActiveSpeakerOnlyConfigurationFactory?.Build();
        result.VerticalLayoutConfiguration ??= VerticalLayoutConfigurationFactory?.Build();
    }

} // End Of Class

